theorem optTiltAtBudget_admissible {sigma2 b budget : ℝ} {n : ℕ}
    (hσ : 0 < sigma2) (hb : 0 < b) (hn : 0 < n) (hbudget : 0 < budget) :
    b * optTiltAtBudget sigma2 b n budget < 3

theorem optTiltAtBudget_pos {sigma2 b budget : ℝ} {n : ℕ}
